//frankra.github.io",aa=JSON.parse(`[{"role":"Staff Software Engineer","company":"Delivery Hero","from":"01/2023","to":"Present","location":"Berlin, Germany","description":"Staff Software Engineer within the vendor data organization of a global local delivery platform operating across 65 countries. Responsible for driving architectural governance, authoring critical RFCs, and spearheading cross-functional initiatives to secure and scale backend infrastructure. Oversees system design patterns for high-traffic services and partners with senior leadership to align technical strategy with business-critical revenue and security objectives.","skills":["Golang","AWS","MySQL","Kubernetes","Kafka","GraphQL","SQS","Redis","Google Wire","Terraform","Grafana","Distributed Systems","System Design (RFC)","Security Hardening"],"activities":[{"description":"Orchestrated the migration of 33 global internal client teams to a secure Security Token Service, eliminating unauthorized admin access risks across the vendor ecosystem, by revoking leaked static JWT tokens and coordinating cross-market authentication flow updates."},{"description":"Spearheaded the implementation of a real-time Kafka-based logistics replacement, recovering ~5 million EUR in annual revenue and saving 75k EUR in infrastructure costs, by conducting a deep-dive business impact analysis and authoring a strategic RFC."},{"description":"Optimized the core vendor service architecture, increasing code coverage by 30% and significantly reducing CI/CD pipeline times, by decoupling layers via interfaces and introducing automated Dependency Injection with Google Wire."},{"description":"Mitigated DDoS vulnerabilities in a federated GraphQL service, improving system stability by whitelisting operations and blocking unoptimized queries, by coordinating a cross-platform rollout and auditing mobile queries via custom Grafana dashboards."},{"description":"Engineered a new organization-wide standard for vendor data validation and PII handling, mitigating an immediate API vulnerability and triggering a global process revamp, by leading an attack surface investigation and auditing internal PII data storage."},{"description":"Eliminated data corruption and race conditions in high-traffic SQS consumers while maintaining parallel processing, by implementing database-level advisory locks and an idempotency tracking framework."}]},{"role":"Lead Software Engineer","company":"Log-hub","from":"11/2021","to":"11/2022","location":"Berlin, Germany","description":"Served as Lead Software Engineer and Deputy CTO for a supply chain analytics firm transitioning from specialized consulting to an integrated SaaS platform model. Spearheaded the architectural design, roadmap planning, and full-lifecycle delivery of the company’s flagship aggregation platform. Managed a cross-border engineering team while establishing organizational standards for engineering governance, infrastructure automation via Kubernetes, and continuous delivery pipelines.","skills":["Node JS","Typescript","Angular","MongoDB","Azure","Kubernetes (AKS)","Docker","CI/CD","Agile/Scrum","Software Architecture"],"activities":[{"description":"Developed a cohesive supply chain analytics and optimization platform, delivering a single-stop-shop for logistics data analysis, by architecting the system and leading a team of 5 engineers."},{"description":"Revitalized team efficiency and deliverable quality, establishing standardized engineering workflows, by implementing SCRUM, code reviews, and product roadmap planning."},{"description":"Executed the migration of 80% of the infrastructure to Azure Kubernetes Service, establishing a foundation for automated continuous releases, by containerizing legacy applications and modernizing the infrastructure stack."},{"description":"Introduced an automated testing culture and integrated tests into the deployment pipeline, greatly reducing the occurrence of regressions and improving software stability."}]},{"role":"Senior Software Engineer","company":"SAP","from":"03/2019","to":"11/2021","location":"Berlin, Germany","description":"Served as a Senior Software Engineer within a startup-like incubator at SAP, a global leader in enterprise software (ERP). Collaborated as a core fullstack engineer on Ruum by SAP, driving the evolution of a lightweight project management tool into a comprehensive workflow management system. Responsible for architecting foundational system components, including API frameworks and integration systems, while maintaining high-level engineering standards across the product's full stack to ensure continuous delivery and technical stability.","skills":["Node JS","Typescript","Angular","PostgreSQL","Terraform","Kubernetes","AWS","OData","API Design","Webhooks"],"activities":[{"description":"Pioneered an annotation-based OData API framework, reducing implementation time from days to hours (~90% savings), by implementing an automated SQL generation layer from model annotations in Node.js."},{"description":"Automated landscape management and environment creation, reducing setup time from days to a couple of hours (~95% savings), by implementing Infrastructure as Code using Terraform."},{"description":"Boosted overall application and public API performance, resolving bottlenecks in slow database queries, by optimizing SQL queries using explain plans, indexes, and views."},{"description":"Architected and developed a complete fullstack webhooks system, allowing developers to conveniently configure, maintain, and troubleshoot integrations."}]},{"role":"Co-Founder / Lead Fullstack Engineer","company":"Flimbo (Deskfy)","from":"03/2015","to":"07/2016","location":"São Leopoldo, Brazil","description":"Co-founded and served as a Lead Fullstack Engineer for a digital marketing SaaS platform focused on streamlining content creation and distribution for social networks. Mandated with the end-to-end architecture and development of the backend services, establishing core application frameworks to standardize security, error handling, and internationalization. Directed strategic business decisions and architectural governance for the frontend, while overseeing the migration to containerized cloud infrastructure and automated CI/CD pipelines to ensure scalable growth.","skills":["Node JS","AngularJS","PostgreSQL","AWS ECS","Docker","Stripe","PassportJS","CI/CD","Entrepreneurship"],"activities":[{"description":"Scaled a digital marketing SaaS platform to 3,600+ users, achieving 1st place in a state entrepreneurship competition, by co-founding the company and leading strategic business and technical decisions."},{"description":"Standardized the development of new features and cross-cutting concerns, ensuring consistent application behavior and high resilience, by designing a custom backend framework leveraging PassportJS and automated paging."},{"description":"Deployed a responsive tile-based UI and a functional payment system for user monetization, by implementing AngularJS with Masonry and integrating Stripe as the payment gateway."},{"description":"Achieved automated deployment and scalable hosting on AWS infrastructure, by configuring CI/CD pipelines and containerizing the application with Docker for Amazon ECS."}]},{"role":"Software Engineer / Architect","company":"SAP","from":"08/2012","to":"03/2019","location":"São Leopoldo, Brazil","description":"Software Engineer and Architect within the Cloud Custom Development organization of a global leader in enterprise ERP software. Mandate included the technical design and delivery of bespoke cloud extensions and standalone systems tailored to specific customer business requirements across diverse industries. Provided architectural leadership for SAP SuccessFactors expansions, ensuring all custom solutions adhered to rigorous enterprise standards for security, scalability, and resource efficiency while guiding engineering teams through complex implementation phases.","skills":["Java EE","Javascript","SAP UI5","D3.js","SAP Cloud Platform","HANA","OData","TDD","Design Thinking"],"activities":[{"description":"Delivered technical customizations for over 20 distinct SAP customers, improving their operational efficiency within the SAP ecosystem, by developing extensions on the Cloud Development Studio platform and facilitating direct customer alignment."},{"description":"Built a real-time IoT monitoring and maintenance prediction dashboard for industrial equipment, reducing potential downtime, by utilizing SAP UI5 and D3.js to visualize live sensor data."},{"description":"Spearheaded high-quality software delivery for Mercedes-AMG, accelerating feedback loops and improving code architecture, by strictly following TDD and Design Thinking while collaborating on-site in Germany."},{"description":"Architected scalable and secure custom extensions for SuccessFactors LMS, accelerating roadmap delivery while ensuring enterprise standard compliance, by designing solutions using Java EE and OData."},{"description":"Authored 'injectjs', an open-source framework for Node.js dependency management, simplifying asynchronous module resolution for the developer community."}]},{"role":"Technical Lead","company":"New Game Entretenimento","from":"01/2008","to":"08/2012","location":"São Leopoldo, Brazil","description":"Served as the sole technical lead for a boutique entertainment provider specializing in the maintenance, restoration, and modernization of legacy arcade systems and retail technology. Orchestrated the full hardware lifecycle, from complex electrical troubleshooting and component-level repair to the design and implementation of custom hardware-software bridges for obsolete equipment. Directed the organization’s digital expansion while overseeing the technical infrastructure and maintenance for auxiliary business units, including high-traffic internet cafés and computer retail services.","skills":["Java","Hardware Hacking","Electrical Engineering","System Administration","Networking","Web Development"],"activities":[{"description":"Restored 100k BRL worth of non-functional arcade inventory, achieving functionality with a minimal investment of 12k BRL, by engineering a modernization strategy involving LCD displays, PC hardware, and custom Java-based coin-op software."},{"description":"Ensured high uptime for the rental fleet and extended the operational life of legacy hardware units, by performing systematic electrical troubleshooting and component-level repair."},{"description":"Maintained a stable and performant computing environment for commercial retail operations, by overseeing the assembly, hardware specification, and maintenance of computer systems and networking."},{"description":"Established the organization's first digital sales and lead generation channel, by developing a portfolio website and social media presence to increase brand visibility."}]}]`),ua=[{title:"14 Awards for Professionalism and Teamwork",institution:"SAP",location:"São Leopoldo, Brazil",date:"2012 - 2019",description:"Awarded multiple times by peers for performance in delivering value to customers and teamwork."},{title:"First Place at UFRGS Entrepreneurship Marathon (Flimbo)",institution:"Universidade Federal do Rio Grande do Sul (UFRGS)",location:"Porto Alegre, Brazil",date:"2016",description:"Flimbo won as the most innovative and overall most mature startup on the event."},{title:"Products and Innovation Talent Award",institution:"SAP",location:"São Leopoldo, Brazil",date:"2015",description:"Nominated one of the talents of the year among the worldwide organization."}],fa=[{title:"Software Analysis and Development (Superior - Part-Time Study)",institution:"Universidade do Vale do Rio dos Sinos (Unisinos)",from:"01/2010",to:"12/2017",level:"Superior",location:"São Leopoldo, Brazil",description:"Thesis focused on clean architecture and dependency injection."}],da=[{name:"Portuguese",proficiency:"Native"},{name:"English",proficiency:"Fluent"},{n